function ProgressionRowItem({ row, batchId, roadmapId, canManage, onSaved }: { row: ProgressionRow; batchId: string; roadmapId: string; canManage: boolean; onSaved: () => Promise<void> }) { const [intent, setIntent] = React.useState(row.intent); const [confirmed, setConfirmed] = React.useState(row.teacherConfirmed); const [note, setNote] = React.useState(row.teacherNote); const [saving, setSaving] = React.useState(false); React.useEffect(() => { setIntent(row.intent); setConfirmed(row.teacherConfirmed); setNote(row.teacherNote); }, [row]); const save = async () => { setSaving(true); try { await saveProgression(batchId, row.studentId, { roadmapId, intent, teacherConfirmed: confirmed, teacherNote: note }); toast.success("Đã lưu quyết định học tập."); await onSaved(); } catch (error) { toast.error(error instanceof Error ? error.message : "Không thể lưu quyết định."); } finally { setSaving(false); } }; const value = (rate: number | null) => rate === null ? "Chưa có" : `${rate}%`; return <tr><td className="px-4 py-3"><p className="font-bold text-slate-800">{row.studentName}</p><p className="text-xs text-slate-400">{row.studentPhone}</p></td><td className="px-4 py-3">{value(row.attendanceRate)}</td><td className="px-4 py-3">{value(row.assignmentRate)}</td><td className="px-4 py-3">{value(row.miniTestRate)}</td><td className="px-4 py-3"><span className={`rounded-full px-2 py-1 text-xs font-bold ${row.eligible ? "bg-emerald-50 text-emerald-700" : "bg-rose-50 text-rose-700"}`}>{row.eligible ? "Đạt" : "Chưa đạt"}</span>{row.eligibilityReasons.length ? <p className="mt-1 max-w-48 text-xs text-rose-600">{row.eligibilityReasons.join("; ")}</p> : null}</td><td className="px-4 py-3"><div className="flex items-center gap-2"><select value={intent} disabled={!canManage} onChange={(event) => setIntent(event.target.value as ProgressionRow["intent"])} className="h-8 rounded border border-slate-200 bg-white px-2 text-xs">{Object.entries(intents).map(([value, label]) => <option value={value} key={value}>{label}</option>)}</select><label className="whitespace-nowrap text-xs text-slate-600"><input type="checkbox" checked={confirmed} disabled={!canManage} onChange={(event) => setConfirmed(event.target.checked)} /> GV xác nhận</label><button type="button" title="Lưu" disabled={!canManage || saving} onClick={() => void save()} className="flex h-8 w-8 items-center justify-center rounded border border-cyan-200 text-cyan-700 disabled:opacity-40"><Check className="h-4 w-4" /></button></div><input value={note} disabled={!canManage} onChange={(event) => setNote(event.target.value)} placeholder="Ghi chú điều phối" className="mt-2 h-8 w-full rounded border border-slate-200 px-2 text-xs" /></td></tr>; }

function Waitlist({ batches, roadmaps, canManage }: { batches: Array<{ id: string; code: string; courseId: string; status: string; learnerIds: string[]; maxLearners: number }>; roadmaps: LearningRoadmap[]; canManage: boolean }) { const [data, setData] = React.useState<{ items: WaitlistRow[]; total: number; totalPages: number }>({ items: [], total: 0, totalPages: 0 }); const [page, setPage] = React.useState(1); const [roadmapId, setRoadmapId] = React.useState(""); const [selected, setSelected] = React.useState<string[]>([]); const [target, setTarget] = React.useState(""); const [loading, setLoading] = React.useState(false); const load = React.useCallback(async () => { setLoading(true); try { const response = await getWaitlist({ page, limit: 25, roadmapId: roadmapId || undefined }); setData(response); setSelected([]); } catch (error) { toast.error(error instanceof Error ? error.message : "Không thể tải danh sách chờ."); } finally { setLoading(false); } }, [page, roadmapId]); React.useEffect(() => { void load(); }, [load]); const chosen = data.items.filter((item) => selected.includes(item.id)); const courseId = chosen[0]?.targetCourseId; const targetBatches = batches.filter((batch) => batch.status === "Sắp khai giảng" && batch.courseId === courseId); const place = async () => { try { await placeWaitlist(target, selected); toast.success("Đã xếp học viên vào lớp đích."); setTarget(""); await load(); window.dispatchEvent(new Event("batch-mutation")); } catch (error) { toast.error(error instanceof Error ? error.message : "Không thể xếp lớp."); } }; return <div className="space-y-4"><div className="flex flex-col gap-3 border border-slate-200 bg-white p-4 lg:flex-row"><select value={roadmapId} onChange={(event) => { setRoadmapId(event.target.value); setPage(1); }} className="h-10 min-w-56 rounded-lg border border-slate-200 bg-white px-3 text-sm"><option value="">Tất cả lộ trình</option>{roadmaps.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><div className="flex flex-1 justify-end gap-2"><select value={target} disabled={!selected.length} onChange={(event) => setTarget(event.target.value)} className="h-10 min-w-64 rounded-lg border border-slate-200 bg-white px-3 text-sm"><option value="">Chọn lớp đích sắp khai giảng</option>{targetBatches.map((batch) => <option key={batch.id} value={batch.id}>{batch.code} · {batch.learnerIds.length}/{batch.maxLearners || "∞"}</option>)}</select>{canManage ? <button type="button" disabled={!target || !selected.length} onClick={() => void place()} className="h-10 rounded-lg bg-cyan-700 px-3 text-xs font-bold text-white disabled:opacity-50">Xếp {selected.length || ""} học viên</button> : null}</div></div>{chosen.some((item) => item.targetCourseId !== courseId) ? <p className="text-sm text-rose-600">Chỉ được xếp học viên cùng mốc đích trong một lần.</p> : null}<div className="overflow-x-auto border border-slate-200 bg-white"><table className="w-full min-w-[850px] text-left text-sm"><thead className="bg-slate-50 text-xs font-bold text-slate-500"><tr><th className="w-12 px-4 py-3"><input type="checkbox" checked={Boolean(data.items.length && selected.length === data.items.length)} onChange={(event) => setSelected(event.target.checked ? data.items.map((item) => item.id) : [])} /></th><th className="px-4 py-3">Học viên</th><th className="px-4 py-3">Lộ trình / mốc</th><th className="px-4 py-3">Lớp nguồn</th><th className="px-4 py-3">Sở thích</th><th className="px-4 py-3">Chờ</th></tr></thead><tbody className="divide-y divide-slate-100">{loading ? <tr><td colSpan={6} className="px-4 py-10 text-center text-slate-500">Đang tải...</td></tr> : data.items.map((item) => <tr key={item.id}><td className="px-4 py-3"><input type="checkbox" checked={selected.includes(item.id)} onChange={(event) => setSelected((current) => event.target.checked ? [...current, item.id] : current.filter((id) => id !== item.id))} /></td><td className="px-4 py-3"><b>{item.studentName}</b><p className="text-xs text-slate-400">{item.studentPhone}</p></td><td className="px-4 py-3"><b>{item.roadmapName}</b><p className="text-xs text-slate-500">{item.targetStepId}</p></td><td className="px-4 py-3">{item.sourceBatchCode}</td><td className="px-4 py-3 text-xs text-slate-600">{item.learningFormat || "Chưa ghi nhận"}{item.preferredTimeSlot ? ` · ${item.preferredTimeSlot}` : ""}</td><td className="px-4 py-3"><b>{item.waitingDays}</b> ngày</td></tr>)}</tbody></table>{!loading && !data.items.length ? <Empty>Chưa có học viên trong danh sách chờ.</Empty> : null}</div><div className="flex items-center justify-between text-sm text-slate-500"><span>{data.total} học viên chờ</span><div className="flex gap-2"><button type="button" disabled={page <= 1} onClick={() => setPage((value) => value - 1)} className="h-8 w-8 rounded border border-slate-200 disabled:opacity-40"><ChevronLeft className="mx-auto h-4 w-4" /></button><span className="py-2 text-xs">Trang {page}/{Math.max(1, data.totalPages)}</span><button type="button" disabled={page >= data.totalPages} onClick={() => setPage((value) => value + 1)} className="h-8 w-8 rounded border border-slate-200 disabled:opacity-40"><ChevronRight className="mx-auto h-4 w-4" /></button></div></div></div>; }

function CreateModal({ courses, onClose, onCreated }: { courses: CourseOption[]; onClose: () => void; onCreated: () => void }) {
  const [steps, setSteps] = React.useState<RoadmapStep[]>([emptyStep(1)]);
  const [saving, setSaving] = React.useState(false);
  const [name, setName] = React.useState("");
  const update = (index: number, patch: Partial<RoadmapStep>) => setSteps((current) => current.map((step, itemIndex) => itemIndex === index ? { ...step, ...patch } : step));
  const selectedCourses = steps.map((step) => courses.find((course) => course.id === step.courseId)).filter((course): course is CourseOption => Boolean(course));
  const routeName = selectedCourses.map((course) => course.title).join(" → ");
  const routeCode = selectedCourses.map((course) => course.code || course.title).join("-").replace(/[^a-zA-Z0-9-]/g, "").slice(0, 50).toUpperCase();
  const selectedIds = new Set(steps.map((step) => step.courseId).filter(Boolean));
  const save = async () => {
    if (steps.some((step) => !step.courseId)) return toast.error("Hãy chọn khóa học cho từng chặng của lộ trình.");
    if (selectedIds.size !== steps.length) return toast.error("Mỗi khóa học chỉ được chọn một lần trong cùng lộ trình.");
    setSaving(true);
    try {
      await createRoadmap({ code: routeCode, name: name.trim() || routeName, description: "", status: "active", steps });
      toast.success("Đã tạo lộ trình từ các khóa học đã chọn.");
      onCreated();
    } catch (error) { toast.error(error instanceof Error ? error.message : "Không thể tạo lộ trình."); } finally { setSaving(false); }
  };
  return <div className="fixed inset-0 z-[80] flex items-center justify-center bg-slate-950/50 p-4"><div className="max-h-[90vh] w-full max-w-3xl overflow-y-auto border border-slate-200 bg-white shadow-2xl"><header className="sticky top-0 flex items-center justify-between border-b border-slate-200 bg-white px-5 py-4"><div><h2 className="font-bold text-slate-900">Tạo lộ trình từ khóa học</h2><p className="mt-1 text-xs text-slate-500">Đặt tên riêng rồi chọn các khóa học theo đúng thứ tự đào tạo.</p></div><button type="button" title="Đóng" onClick={onClose} className="p-2 text-slate-500"><X className="h-4 w-4" /></button></header><div className="space-y-4 p-5"><input value={name} onChange={(event) => setName(event.target.value)} placeholder="Tên lộ trình (ví dụ: Lộ trình tiếng Trung sơ cấp)" className="h-10 w-full rounded border border-slate-200 px-3 text-sm" /><div className="border border-cyan-100 bg-cyan-50 px-3 py-2 text-sm font-semibold text-cyan-800">{routeName || "Chọn khóa học để bắt đầu lộ trình"}</div>{steps.map((step, index) => <div key={step.id} className="space-y-2 border border-slate-200 bg-slate-50 p-3"><div className="grid gap-2 md:grid-cols-[40px_1fr_110px_110px_auto]"><span className="flex h-9 w-9 items-center justify-center rounded-full bg-cyan-100 text-sm font-bold text-cyan-700">{step.order}</span><select value={step.courseId} onChange={(event) => update(index, { courseId: event.target.value })} className="h-9 rounded border border-slate-200 bg-white px-2 text-sm"><option value="">Chọn khóa học</option>{courses.map((course) => <option value={course.id} key={course.id} disabled={course.id !== step.courseId && selectedIds.has(course.id)}>{course.title}</option>)}</select><input type="number" min="0" value={step.minClassSize || ""} onChange={(event) => update(index, { minClassSize: Number(event.target.value) || 0 })} placeholder="Sĩ số tối thiểu" className="h-9 rounded border border-slate-200 px-2 text-xs" /><input type="number" min="0" value={step.maxClassSize || ""} onChange={(event) => update(index, { maxClassSize: Number(event.target.value) || 0 })} placeholder="Sĩ số tối đa" className="h-9 rounded border border-slate-200 px-2 text-xs" /><button type="button" title="Xóa chặng" disabled={steps.length === 1} onClick={() => setSteps((current) => current.filter((_, itemIndex) => itemIndex !== index).map((item, itemIndex) => ({ ...item, order: itemIndex + 1 })))} className="h-9 w-9 rounded border border-rose-200 text-rose-600 disabled:opacity-30"><X className="mx-auto h-4 w-4" /></button></div><div className="grid gap-2 md:grid-cols-4"><input type="number" min="0" max="100" value={step.eligibilityPolicy.minAttendanceRate ?? ""} onChange={(event) => update(index, { eligibilityPolicy: { ...step.eligibilityPolicy, minAttendanceRate: event.target.value === "" ? null : Number(event.target.value) } })} placeholder="Chuyên cần %" className="h-8 rounded border border-slate-200 bg-white px-2 text-xs" /><input type="number" min="0" max="100" value={step.eligibilityPolicy.minAssignmentRate ?? ""} onChange={(event) => update(index, { eligibilityPolicy: { ...step.eligibilityPolicy, minAssignmentRate: event.target.value === "" ? null : Number(event.target.value) } })} placeholder="Bài tập %" className="h-8 rounded border border-slate-200 bg-white px-2 text-xs" /><input type="number" min="0" max="100" value={step.eligibilityPolicy.minMiniTestRate ?? ""} onChange={(event) => update(index, { eligibilityPolicy: { ...step.eligibilityPolicy, minMiniTestRate: event.target.value === "" ? null : Number(event.target.value) } })} placeholder="Mini test %" className="h-8 rounded border border-slate-200 bg-white px-2 text-xs" /><label className="flex h-8 items-center gap-2 text-xs text-slate-600"><input type="checkbox" checked={step.eligibilityPolicy.teacherConfirmationRequired} onChange={(event) => update(index, { eligibilityPolicy: { ...step.eligibilityPolicy, teacherConfirmationRequired: event.target.checked } })} />Cần GV xác nhận</label></div></div>)}<button type="button" onClick={() => setSteps((current) => [...current, emptyStep(current.length + 1)])} className="inline-flex h-9 items-center gap-2 rounded-lg border border-cyan-200 px-3 text-xs font-bold text-cyan-700"><Plus className="h-4 w-4" />Thêm khóa học tiếp theo</button><div className="flex justify-end gap-2 border-t border-slate-200 pt-4"><button type="button" onClick={onClose} className="h-9 rounded-lg border border-slate-200 px-3 text-xs font-bold text-slate-600">Hủy</button><button type="button" disabled={saving || !routeName} onClick={() => void save()} className="h-9 rounded-lg bg-cyan-700 px-3 text-xs font-bold text-white disabled:opacity-50">Lưu lộ trình</button></div></div></div></div>;
}

function CreateModalBulk({ courses, onClose, onCreated }: { courses: CourseOption[]; onClose: () => void; onCreated: () => void }) {
  const [steps, setSteps] = React.useState<RoadmapStep[]>([emptyStep(1)]);
  const [name, setName] = React.useState("");
  const [saving, setSaving] = React.useState(false);
  const [policy, setPolicy] = React.useState<RoadmapStep["eligibilityPolicy"]>({
    matchMode: "all", minAttendanceRate: null, minAssignmentRate: null, minMiniTestRate: null, minExamRate: null, teacherConfirmationRequired: false,
  });

  const updateStep = (index: number, patch: Partial<RoadmapStep>) => setSteps((current) => current.map((step, stepIndex) => stepIndex === index ? { ...step, ...patch } : step));
  const selectedIds = new Set(steps.map((step) => step.courseId).filter(Boolean));
  const selectedCourses = steps.map((step) => courses.find((course) => course.id === step.courseId)).filter((course): course is CourseOption => Boolean(course));
  const routeName = selectedCourses.map((course) => course.title).join(" → ");
  const routeCode = selectedCourses.map((course) => course.code || course.title).join("-").replace(/[^a-zA-Z0-9-]/g, "").slice(0, 50).toUpperCase();
  const changeThreshold = (key: "minAttendanceRate" | "minAssignmentRate" | "minMiniTestRate" | "minExamRate", value: string) => setPolicy((current) => ({ ...current, [key]: value === "" ? null : Number(value) }));
  const removeStep = (index: number) => setSteps((current) => current.filter((_, stepIndex) => stepIndex !== index).map((step, stepIndex) => ({ ...step, order: stepIndex + 1 })));
  const applyPolicy = () => setSteps((current) => current.map((step) => ({ ...step, eligibilityPolicy: { ...policy } })));

  const save = async () => {
    if (steps.some((step) => !step.courseId)) return toast.error("Hãy chọn khóa học cho từng chặng của lộ trình.");
    if (selectedIds.size !== steps.length) return toast.error("Mỗi khóa học chỉ được chọn một lần trong cùng lộ trình.");
    setSaving(true);
    try {
      await createRoadmap({ code: routeCode, name: name.trim() || routeName, description: "", status: "active", steps: steps.map((step) => ({ ...step, eligibilityPolicy: { ...policy } })) });
      toast.success("Đã tạo lộ trình và áp dụng thiết lập chung cho các chặng.");
      onCreated();
    } catch (error) { toast.error(error instanceof Error ? error.message : "Không thể tạo lộ trình."); } finally { setSaving(false); }
  };

  return <div className="fixed inset-0 z-[80] flex items-center justify-center bg-slate-950/50 p-4"><section className="max-h-[90vh] w-full max-w-4xl overflow-y-auto rounded-xl border border-slate-200 bg-white shadow-2xl"><header className="sticky top-0 z-10 flex items-start justify-between border-b border-slate-200 bg-white px-6 py-5"><div><h2 className="text-lg font-bold text-slate-900">Tạo lộ trình từ khóa học</h2><p className="mt-1 text-sm text-slate-500">Chọn các khóa học theo đúng thứ tự đào tạo. Điều kiện lên chặng được nhập một lần cho toàn bộ lộ trình.</p></div><button type="button" title="Đóng" onClick={onClose} className="rounded p-2 text-slate-500 hover:bg-slate-100"><X className="h-5 w-5" /></button></header><div className="space-y-5 p-6"><label className="block text-xs font-bold uppercase tracking-wide text-slate-500">Tên lộ trình<input value={name} onChange={(event) => setName(event.target.value)} placeholder="Để trống để tự tạo từ các khóa học" className="mt-2 h-10 w-full rounded-lg border border-slate-200 px-3 text-sm outline-none focus:border-cyan-500" /></label><div className="rounded-lg border border-cyan-100 bg-cyan-50 px-4 py-3 text-sm font-semibold text-cyan-800">{routeName || "Chọn khóa học để bắt đầu lộ trình"}</div><section className="rounded-xl border border-slate-200 bg-slate-50 p-4"><div className="mb-3 flex flex-wrap items-center justify-between gap-2"><div><h3 className="text-sm font-bold text-slate-800">Thiết lập chung</h3><p className="mt-1 text-xs text-slate-500">Các điều kiện này sẽ áp dụng đồng loạt cho tất cả chặng.</p></div><button type="button" onClick={applyPolicy} className="h-8 rounded-lg border border-cyan-200 bg-white px-3 text-xs font-bold text-cyan-700 hover:bg-cyan-50">Áp dụng cho {steps.length} chặng</button></div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><label className="text-xs font-semibold text-slate-600">Chuyên cần %<input type="number" min="0" max="100" value={policy.minAttendanceRate ?? ""} onChange={(event) => changeThreshold("minAttendanceRate", event.target.value)} className="mt-1 h-9 w-full rounded-lg border border-slate-200 bg-white px-2 text-sm" placeholder="Không yêu cầu" /></label><label className="text-xs font-semibold text-slate-600">Bài tập %<input type="number" min="0" max="100" value={policy.minAssignmentRate ?? ""} onChange={(event) => changeThreshold("minAssignmentRate", event.target.value)} className="mt-1 h-9 w-full rounded-lg border border-slate-200 bg-white px-2 text-sm" placeholder="Không yêu cầu" /></label><label className="text-xs font-semibold text-slate-600">Mini test %<input type="number" min="0" max="100" value={policy.minMiniTestRate ?? ""} onChange={(event) => changeThreshold("minMiniTestRate", event.target.value)} className="mt-1 h-9 w-full rounded-lg border border-slate-200 bg-white px-2 text-sm" placeholder="Không yêu cầu" /></label><label className="text-xs font-semibold text-slate-600">Điểm thi %<input type="number" min="0" max="100" value={policy.minExamRate ?? ""} onChange={(event) => changeThreshold("minExamRate", event.target.value)} className="mt-1 h-9 w-full rounded-lg border border-slate-200 bg-white px-2 text-sm" placeholder="Không yêu cầu" /></label></div><label className="mt-3 inline-flex items-center gap-2 text-xs font-semibold text-slate-600"><input type="checkbox" checked={policy.teacherConfirmationRequired} onChange={(event) => setPolicy((current) => ({ ...current, teacherConfirmationRequired: event.target.checked }))} className="h-4 w-4 rounded border-slate-300 text-cyan-700" />Cần giáo viên xác nhận trước khi lên chặng</label></section><section className="space-y-3"><h3 className="text-sm font-bold text-slate-800">Các chặng đào tạo</h3>{steps.map((step, index) => <div key={step.id} className="grid items-end gap-3 rounded-xl border border-slate-200 bg-white p-3 md:grid-cols-[40px_minmax(0,1fr)_130px_130px_36px]"><span className="mb-0.5 flex h-9 w-9 items-center justify-center rounded-full bg-cyan-100 text-sm font-bold text-cyan-700">{step.order}</span><label className="min-w-0 text-xs font-semibold text-slate-600">Khóa học<RoadmapPicker value={step.courseId} placeholder="Chọn khóa học" options={courses.filter((course) => course.id === step.courseId || !selectedIds.has(course.id)).map((course) => ({ value: course.id, label: course.title }))} onChange={(courseId) => updateStep(index, { courseId })} className="mt-1" /></label><label className="text-xs font-semibold text-slate-600">Sĩ số tối thiểu<input type="number" min="0" value={step.minClassSize || ""} onChange={(event) => updateStep(index, { minClassSize: Number(event.target.value) || 0 })} className="mt-1 h-9 w-full rounded-lg border border-slate-200 px-2 text-sm" /></label><label className="text-xs font-semibold text-slate-600">Sĩ số tối đa<input type="number" min="0" value={step.maxClassSize || ""} onChange={(event) => updateStep(index, { maxClassSize: Number(event.target.value) || 0 })} className="mt-1 h-9 w-full rounded-lg border border-slate-200 px-2 text-sm" /></label><button type="button" title="Xóa chặng" disabled={steps.length === 1} onClick={() => removeStep(index)} className="mb-0.5 flex h-9 w-9 items-center justify-center rounded-lg border border-rose-200 text-rose-600 disabled:opacity-30"><X className="h-4 w-4" /></button></div>)}</section><button type="button" onClick={() => setSteps((current) => [...current, emptyStep(current.length + 1)])} className="inline-flex h-9 items-center gap-2 rounded-lg border border-cyan-200 px-3 text-xs font-bold text-cyan-700 hover:bg-cyan-50"><Plus className="h-4 w-4" />Thêm khóa học tiếp theo</button><div className="flex justify-end gap-2 border-t border-slate-200 pt-4"><button type="button" onClick={onClose} className="h-9 rounded-lg border border-slate-200 px-4 text-xs font-bold text-slate-600">Hủy</button><button type="button" disabled={saving || !routeName} onClick={() => void save()} className="h-9 rounded-lg bg-cyan-700 px-4 text-xs font-bold text-white disabled:opacity-50">{saving ? "Đang lưu..." : "Lưu lộ trình"}</button></div></div></section></div>;
}

function CreateModalWithBulk({ courses, onClose, onCreated }: { courses: CourseOption[]; onClose: () => void; onCreated: () => void }) {
  const [steps, setSteps] = React.useState<RoadmapStep[]>([emptyStep(1)]);
  const [name, setName] = React.useState("");
  const [saving, setSaving] = React.useState(false);
  const [bulkPolicy, setBulkPolicy] = React.useState<RoadmapStep["eligibilityPolicy"]>({ matchMode: "all", minAttendanceRate: null, minAssignmentRate: null, minMiniTestRate: null, minExamRate: null, teacherConfirmationRequired: false });
  const update = (index: number, patch: Partial<RoadmapStep>) => setSteps((current) => current.map((step, stepIndex) => stepIndex === index ? { ...step, ...patch } : step));
  const updateStepPolicy = (index: number, key: "minAttendanceRate" | "minAssignmentRate" | "minMiniTestRate" | "minExamRate", value: string) => setSteps((current) => current.map((step, stepIndex) => stepIndex === index ? { ...step, eligibilityPolicy: { ...step.eligibilityPolicy, [key]: value === "" ? null : Number(value) } } : step));
  const updateBulk = (key: "minAttendanceRate" | "minAssignmentRate" | "minMiniTestRate" | "minExamRate", value: string) => setBulkPolicy((current) => ({ ...current, [key]: value === "" ? null : Number(value) }));
  const selectedIds = new Set(steps.map((step) => step.courseId).filter(Boolean));
  const selectedCourses = steps.map((step) => courses.find((course) => course.id === step.courseId)).filter((course): course is CourseOption => Boolean(course));
  const routeName = selectedCourses.map((course) => course.title).join(" → ");
  const routeCode = selectedCourses.map((course) => course.code || course.title).join("-").replace(/[^a-zA-Z0-9-]/g, "").slice(0, 50).toUpperCase();
  const applyBulk = () => setSteps((current) => current.map((step) => ({ ...step, eligibilityPolicy: { ...bulkPolicy } })));
  const remove = (index: number) => setSteps((current) => current.filter((_, stepIndex) => stepIndex !== index).map((step, stepIndex) => ({ ...step, order: stepIndex + 1 })));
  const save = async () => { if (steps.some((step) => !step.courseId)) return toast.error("Hãy chọn khóa học cho từng chặng của lộ trình."); if (selectedIds.size !== steps.length) return toast.error("Mỗi khóa học chỉ được chọn một lần trong cùng lộ trình."); setSaving(true); try { await createRoadmap({ code: routeCode, name: name.trim() || routeName, description: "", status: "active", steps }); toast.success("Đã tạo lộ trình."); onCreated(); } catch (error) { toast.error(error instanceof Error ? error.message : "Không thể tạo lộ trình."); } finally { setSaving(false); } };
  const threshold = (label: string, value: number | null, onChange: (value: string) => void) => <label className="text-xs font-semibold text-slate-600">{label}<input type="number" min="0" max="100" value={value ?? ""} onChange={(event) => onChange(event.target.value)} placeholder="Nhập ngưỡng, VD: 50" className="mt-1 h-8 w-full rounded-lg border border-slate-200 bg-white px-2 text-xs" /></label>;
  return <div className="fixed inset-0 z-[80] flex items-center justify-center bg-slate-950/50 p-4"><section className="max-h-[90vh] w-full max-w-4xl overflow-y-auto rounded-xl border border-slate-200 bg-white shadow-2xl"><header className="sticky top-0 z-10 flex items-start justify-between border-b border-slate-200 bg-white px-6 py-5"><div><h2 className="text-lg font-bold text-slate-900">Tạo lộ trình từ khóa học</h2><p className="mt-1 text-sm text-slate-500">Thiết lập điều kiện riêng cho từng chặng, hoặc dùng bulk để điền nhanh khi các chặng giống nhau.</p></div><button type="button" title="Đóng" onClick={onClose} className="rounded p-2 text-slate-500 hover:bg-slate-100"><X className="h-5 w-5" /></button></header><div className="space-y-5 p-6"><label className="block text-xs font-bold uppercase tracking-wide text-slate-500">Tên lộ trình<input value={name} onChange={(event) => setName(event.target.value)} placeholder="Để trống để tự tạo từ các khóa học" className="mt-2 h-10 w-full rounded-lg border border-slate-200 px-3 text-sm outline-none focus:border-cyan-500" /></label><div className="rounded-lg border border-cyan-100 bg-cyan-50 px-4 py-3 text-sm font-semibold text-cyan-800">{routeName || "Chọn khóa học để bắt đầu lộ trình"}</div><section className="rounded-xl border border-dashed border-cyan-300 bg-cyan-50/50 p-4"><div className="mb-3 flex flex-wrap items-center justify-between gap-2"><div><h3 className="text-sm font-bold text-cyan-900">Điền nhanh điều kiện (Bulk)</h3><p className="mt-1 text-xs text-slate-500">Tùy chọn: bấm áp dụng để sao chép vào tất cả chặng, sau đó vẫn có thể sửa riêng từng chặng.</p></div><button type="button" onClick={applyBulk} className="h-8 rounded-lg bg-cyan-700 px-3 text-xs font-bold text-white hover:bg-cyan-800">Áp dụng cho {steps.length} chặng</button></div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{threshold("Chuyên cần %", bulkPolicy.minAttendanceRate, (value) => updateBulk("minAttendanceRate", value))}{threshold("Bài tập %", bulkPolicy.minAssignmentRate, (value) => updateBulk("minAssignmentRate", value))}{threshold("Mini test %", bulkPolicy.minMiniTestRate, (value) => updateBulk("minMiniTestRate", value))}{threshold("Điểm thi %", bulkPolicy.minExamRate, (value) => updateBulk("minExamRate", value))}</div><label className="mt-3 inline-flex items-center gap-2 text-xs font-semibold text-slate-600"><input type="checkbox" checked={bulkPolicy.teacherConfirmationRequired} onChange={(event) => setBulkPolicy((current) => ({ ...current, teacherConfirmationRequired: event.target.checked }))} className="h-4 w-4 rounded border-slate-300 text-cyan-700" />Cần giáo viên xác nhận</label></section><section className="space-y-3"><h3 className="text-sm font-bold text-slate-800">Thiết lập riêng theo từng chặng</h3>{steps.map((step, index) => <div key={step.id} className="rounded-xl border border-slate-200 bg-white p-4"><div className="grid items-end gap-3 md:grid-cols-[40px_minmax(0,1fr)_130px_130px_36px]"><span className="mb-0.5 flex h-9 w-9 items-center justify-center rounded-full bg-cyan-100 text-sm font-bold text-cyan-700">{step.order}</span><label className="min-w-0 text-xs font-semibold text-slate-600">Khóa học<RoadmapPicker value={step.courseId} placeholder="Chọn khóa học" options={courses.filter((course) => course.id === step.courseId || !selectedIds.has(course.id)).map((course) => ({ value: course.id, label: course.title }))} onChange={(courseId) => update(index, { courseId })} className="mt-1" /></label><label className="text-xs font-semibold text-slate-600">Sĩ số tối thiểu<input type="number" min="0" value={step.minClassSize || ""} onChange={(event) => update(index, { minClassSize: Number(event.target.value) || 0 })} className="mt-1 h-9 w-full rounded-lg border border-slate-200 px-2 text-sm" /></label><label className="text-xs font-semibold text-slate-600">Sĩ số tối đa<input type="number" min="0" value={step.maxClassSize || ""} onChange={(event) => update(index, { maxClassSize: Number(event.target.value) || 0 })} className="mt-1 h-9 w-full rounded-lg border border-slate-200 px-2 text-sm" /></label><button type="button" title="Xóa chặng" disabled={steps.length === 1} onClick={() => remove(index)} className="mb-0.5 flex h-9 w-9 items-center justify-center rounded-lg border border-rose-200 text-rose-600 disabled:opacity-30"><X className="h-4 w-4" /></button></div><div className="mt-3 grid gap-3 border-t border-slate-100 pt-3 sm:grid-cols-2 lg:grid-cols-4">{threshold("Chuyên cần %", step.eligibilityPolicy.minAttendanceRate, (value) => updateStepPolicy(index, "minAttendanceRate", value))}{threshold("Bài tập %", step.eligibilityPolicy.minAssignmentRate, (value) => updateStepPolicy(index, "minAssignmentRate", value))}{threshold("Mini test %", step.eligibilityPolicy.minMiniTestRate, (value) => updateStepPolicy(index, "minMiniTestRate", value))}{threshold("Điểm thi %", step.eligibilityPolicy.minExamRate, (value) => updateStepPolicy(index, "minExamRate", value))}</div><label className="mt-3 inline-flex items-center gap-2 text-xs font-semibold text-slate-600"><input type="checkbox" checked={step.eligibilityPolicy.teacherConfirmationRequired} onChange={(event) => update(index, { eligibilityPolicy: { ...step.eligibilityPolicy, teacherConfirmationRequired: event.target.checked } })} className="h-4 w-4 rounded border-slate-300 text-cyan-700" />Cần giáo viên xác nhận cho chặng này</label></div>)}</section><button type="button" onClick={() => setSteps((current) => [...current, emptyStep(current.length + 1)])} className="inline-flex h-9 items-center gap-2 rounded-lg border border-cyan-200 px-3 text-xs font-bold text-cyan-700 hover:bg-cyan-50"><Plus className="h-4 w-4" />Thêm khóa học tiếp theo</button><div className="flex justify-end gap-2 border-t border-slate-200 pt-4"><button type="button" onClick={onClose} className="h-9 rounded-lg border border-slate-200 px-4 text-xs font-bold text-slate-600">Hủy</button><button type="button" disabled={saving || !routeName} onClick={() => void save()} className="h-9 rounded-lg bg-cyan-700 px-4 text-xs font-bold text-white disabled:opacity-50">{saving ? "Đang lưu..." : "Lưu lộ trình"}</button></div></div></section></div>;
}
